// WithPrAndIssueQueryParams builds a URL for creating an issue or pull request via GitHub's web
// UI, encoding the provided metadata as query parameters. Note that the web UI expects projects
// to be identified by their resource path (e.g. "OWNER/REPO/projects/1"), unlike the GraphQL API
// which accepts project names, so project names are resolved to paths here.
func WithPrAndIssueQueryParams(client *api.Client, baseRepo ghrepo.Interface, baseURL string, state IssueMetadataState) (string, error) {
	u, err := url.Parse(baseURL)
	if err != nil {
		return "", err
	}
	q := u.Query()
	if state.Title != "" {
		q.Set("title", state.Title)
	}
	if state.Body != "" {
		q.Set("body", state.Body)
	}
	if len(state.Assignees) > 0 {
		q.Set("assignees", strings.Join(state.Assignees, ","))
	}
	if len(state.Labels) > 0 {
		q.Set("labels", strings.Join(state.Labels, ","))
	}
	if len(state.Projects) > 0 {
		if err := fillMetadata(client, baseRepo, &state); err != nil {
			return "", err
		}
		projectPaths, err := state.MetadataResult.ProjectsToPaths(state.Projects)
		if err != nil {
			return "", err
		}
		q.Set("projects", strings.Join(projectPaths, ","))
	}

